#ifndef MSDOS_ROM_TABLE_H
#define MSDOS_ROM_TABLE_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
    const char *path;       /* 86Box's, under roms/ */
    uint32_t size;
    uint32_t crc32;
} msdos_rom_file;

#define MSDOS_ROM_MAX_VARIANTS 4
#define MSDOS_ROM_MAX_FILES    4

typedef struct {
    const char *bios;       /* the BIOS choice it is, or NULL */
    int nfiles;
    int files[MSDOS_ROM_MAX_FILES];     /* indices into msdos_rom_files */
} msdos_rom_variant;

typedef struct {
    const char *key;
    const char *name;
    const char *group;
    const char *section;    /* 86box.cfg section holding the BIOS choice */
    int nvariants;
    msdos_rom_variant variants[MSDOS_ROM_MAX_VARIANTS];
} msdos_rom_item_def;

extern const char msdos_rom_table_source[];
extern const msdos_rom_file msdos_rom_files[];
extern const int msdos_rom_file_count;
extern const msdos_rom_item_def msdos_rom_items[];
extern const int msdos_rom_item_count;

#endif
